        return interaction.reply({ content: 'Je ne peux pas bannir cet utilisateur car je n\'ai pas la permission de rejoindre ce salon vocal.', ephemeral: true });
      }
    } else {
      return interaction.reply({ content: 'Je ne peux pas bannir cet utilisateur car je ne suis pas sur ce serveur.', ephemeral: true });
    }

    // Bannissez l'utilisateur
